<template><div class="page"><div class="page-head"><div><h1 class="page-title">素材中心</h1><div class="page-subtitle">管理公众号永久素材</div></div><div class="toolbar"><el-select v-model="type" @change="load" style="width:120px"><el-option label="图片" value="image"/><el-option label="语音" value="voice"/><el-option label="视频" value="video"/></el-select><el-upload :show-file-list="false" :http-request="upload"><el-button type="primary">上传素材</el-button></el-upload></div></div><div class="asset-grid" v-loading="loading"><article v-for="item in list" :key="item.mediaId" class="surface asset"><el-image v-if="type==='image'" :src="item.url" fit="contain"/><div v-else class="file-icon">{{type==='voice'?'音频':'视频'}}</div><p>{{item.name||item.mediaId}}</p><el-popconfirm title="确定删除素材？" @confirm="remove(item.mediaId)"><template #reference><el-button text type="danger">删除</el-button></template></el-popconfirm></article></div></div></template>
<script setup>import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'@/api/console';const type=ref('image'),list=ref([]),loading=ref(false);async function load(){loading.value=true;try{const r=await api.materials({type:type.value,page:1});list.value=r.data?.items||r.data?.item||[]}finally{loading.value=false}}async function upload({file}){const d=new FormData();d.append('file',file);d.append('fileName',file.name);d.append('mediaType',type.value);await api.uploadMaterial(d);ElMessage.success('上传成功');load()}async function remove(mediaId){await api.deleteMaterial({mediaId});ElMessage.success('已删除');load()}onMounted(load)</script><style scoped>.asset-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.asset{padding:10px;min-height:180px}.asset :deep(.el-image){width:100%;height:125px}.asset p{font-size:12px;word-break:break-all}.file-icon{height:125px;display:grid;place-items:center;background:#edf1f6;color:#70809b}</style>
